/* ================= More slide lessons: EA Part 2 (businesses) and Part 3 (representation) =================
   Added after a review found Part 2 had 21 slides and Part 3 had 16, against 144 in Part 1.
   Every rule and number on these slides is taken from the fact cards already in this app (tax year 2025 law, including
   the 2025 OBBBA changes), so the lessons and the questions agree. People and amounts in examples are invented.
   New units are appended after the existing ones, so saved lesson positions are not disturbed. */
/* ---------------- Part 2: Businesses ---------------- */
U(2,"Accounting methods, tax years and inventory",/cash method|accrual|gross receipts test|tax year|fiscal year|inventory|LIFO|FIFO|UNICAP|263A|3115|1128|constructive receipt/i,[
 {h:"Cash or accrual",v:{k:"cmp",a:["Cash method",["Income when received, or made available to you (constructive receipt)","Expenses when paid","Not allowed for C corporations, or partnerships with a C corporation partner, unless they pass the gross receipts test"]],b:["Accrual method",["Income when all events fix the right to it and the amount can be figured with reasonable accuracy","Expenses when incurred","Never later than when the income shows on the financial statements"]]}},
 {h:"The small business gross receipts test",b:["For 2025: average annual gross receipts of $31 million or less over the prior 3 years.","Passing it allows the cash method, and frees the business from the uniform capitalization rules (Section 263A), the business interest limit and formal inventory accounting.","It is the single most useful threshold in Part 2: learn what it unlocks."]},
 {h:"Tax years",b:["A fiscal year is 12 months ending in any month except December.","A partnership must use, in order: the majority-interest tax year, then the principal partners' year, then the year with the least aggregate deferral.","Any other year needs a business purpose or a Section 444 election.","Changing a tax year: Form 1128. Changing an accounting method: Form 3115."]},
 {h:"Inventory",b:["Inventory is raw materials, work in process, finished goods and merchandise bought for resale.","Methods: FIFO, LIFO (elected on Form 970) or specific identification. Lower of cost or market cannot be used with LIFO.","A business that passes the gross receipts test may treat inventory as non-incidental materials and supplies.","Cost of goods sold: beginning inventory, plus purchases and production costs, minus ending inventory (Form 1125-A)."],
  ex:"A C corporation that used LIFO and becomes an S corporation adds its LIFO reserve to income in its last C year and pays that tax in 4 equal installments."}
]);
U(2,"Business deductions that have their own rules",/meal|entertainment|gift|travel|mileage|home office|startup|organizational|bad debt|repair|de minimis|research|ordinary and necessary|8829/i,[
 {h:"The starting test",b:["A business expense must be ordinary (common in that trade) and necessary (helpful to the business).","A capital expenditure creates or improves a long-lived asset. It is capitalized and recovered through depreciation, not deducted at once.","Capitalize betterments, restorations and adaptations to a new use. Deduct routine repairs and maintenance.","De minimis safe harbor: by election, deduct items costing up to $2,500 per invoice or item ($5,000 with an applicable financial statement)."]},
 {h:"Meals, entertainment, gifts and travel",v:{k:"tiers",r:[["Business meals","50% if not lavish and the taxpayer or an employee is present",50],["Entertainment","0%",5],["Company-wide holiday party","100%",100],["Business gifts","$25 per recipient per year",25],["Travel away from home overnight","Transportation and lodging 100%, meals 50%",75]]},
  ex:"A spouse's travel costs are deductible only if the spouse is a real employee with a business purpose for the trip."},
 {h:"Vehicles and the home office",b:["Car, standard mileage rate for 2025: 70 cents a mile, plus parking and tolls. It must be chosen in the first year the car is used for business, and it is not available for 5 or more vehicles used at the same time.","Car, actual expenses: gas, repairs, insurance, depreciation and registration, times the business-use percentage. Commuting is never business.","Home office: regular and exclusive use as the principal place of business, or to meet clients, or a separate structure. Employees cannot deduct one.","Simplified method: $5 a square foot, up to 300 square feet ($1,500). Regular method: Form 8829."]},
 {h:"Costs before and around the business",b:["Startup costs and organizational costs: deduct up to $5,000 of each in the first year. The $5,000 shrinks dollar for dollar once the costs pass $50,000. The rest is amortized over 180 months.","Domestic research and experimental costs are immediately deductible again for tax years beginning after 2024. Foreign research is still amortized over 15 years.","Business bad debt: an ordinary deduction when wholly or partly worthless, but only if the amount was included in income before. A cash-method business cannot deduct an uncollected fee.","Nonbusiness bad debt: a short-term capital loss, and only when totally worthless."]}
]);
U(2,"Loss limits, net operating losses and the QBI deduction",/at-risk|passive|excess business loss|hobby|net operating loss|NOL|QBI|199A|SSTB|UBIA|8995|6198|8582|Form 461/i,[
 {h:"Four hurdles for a pass-through loss, in order",v:{k:"flow",r:["1. Basis: a loss cannot exceed the owner's basis","2. At-risk limit (Form 6198)","3. Passive activity limit (Form 8582)","4. Excess business loss limit (Form 461)"]},
  ex:"For 2025 the excess business loss limit is $313,000, or $626,000 on a joint return. The excess becomes a net operating loss carryforward."},
 {h:"Net operating losses and hobbies",b:["NOLs arising after 2020: no carryback, carried forward without a time limit, and the deduction is limited to 80% of taxable income.","Farm losses are the exception: they may be carried back 2 years.","Hobby rule: an activity is presumed to be for profit if it showed a profit in 3 of 5 years (2 of 7 for horses).","Hobby income is taxable. Hobby expenses are not deductible."]},
 {h:"The qualified business income deduction",b:["20% of qualified business income from sole proprietorships, partnerships and S corporations (Section 199A), made permanent by the 2025 law. C corporations cannot claim it.","2025 threshold: taxable income of $197,300, or $394,600 on a joint return.","Above the threshold two limits phase in over the next $50,000 ($100,000 joint): the specified service business rule and the wage and property limit.","Form 8995 at or below the threshold; Form 8995-A above it."]},
 {h:"The two limits above the threshold",v:{k:"cmp",a:["Specified service business (SSTB)",["Health, law, accounting, actuarial science, performing arts, consulting, athletics, financial and brokerage services","Or any business whose main asset is the reputation or skill of its owners","Its deduction phases out completely"]],b:["Wage and property limit",["The deduction cannot exceed the greater of:","50% of W-2 wages, or","25% of W-2 wages plus 2.5% of the unadjusted basis of qualified property (UBIA)"]]}}
]);
U(2,"Partnerships: sales, liquidations and special rules",/sale of a partnership interest|hot asset|751|liquidating|754|704\(c\)|disguised sale|partnership terminat|partnership representative|recourse|1446|8804|pass-through entity tax|PTET/i,[
 {h:"Selling a partnership interest",b:["Amount realized: cash, plus the value of property received, plus the selling partner's share of partnership liabilities that the buyer takes over.","The gain or loss is capital, except the part that comes from hot assets (Section 751): unrealized receivables and inventory. That part is ordinary.","The partnership's tax year closes for the selling partner on the date of sale.","A Section 754 election lets the partnership adjust the basis of its own assets after a transfer of an interest or a distribution."]},
 {h:"Liquidating distributions",v:{k:"cmp",a:["Gain",["Only when cash received is more than the partner's outside basis","Relief from liabilities counts as cash"]],b:["Loss",["Only if the partner receives nothing but cash, unrealized receivables and inventory","And the outside basis is more than those total"]]},
  b:["Basis of property received in liquidation: outside basis minus cash; unrealized receivables and inventory take the partnership's basis; all remaining basis goes to the other property."],
  ex:"In a nonliquidating distribution the partnership's basis in the property carries over, but never more than the partner's outside basis reduced by cash received."},
 {h:"Contributed property and liabilities",b:["Contributing property for an interest is not taxed (Section 721).","Built-in gain or loss on contributed property is allocated back to the contributing partner when the partnership sells it (Section 704(c)).","A contribution followed within 2 years by a distribution to the same partner is presumed to be a disguised sale.","A partner's share of recourse debt follows who bears the economic risk of loss; nonrecourse debt generally follows the profit-sharing ratio."]},
 {h:"Other partnership rules the exam likes",b:["A partnership terminates only when no part of its business is carried on by any partner in a partnership.","Audits: the partnership names a partnership representative. A partnership with 100 or fewer eligible partners may elect out of the centralized audit regime each year.","Foreign partners: the partnership pays withholding tax on effectively connected income allocable to them (37% for individuals and 21% for corporations in 2025), on Form 8804, with a Form 8805 to each foreign partner.","A state pass-through entity tax paid by the partnership or S corporation is deducted by the entity, so it is not caught by the owners' limit on state and local taxes.","Limited partners do not pay self-employment tax on their distributive share, only on guaranteed payments for services."]}
]);
U(2,"S corporations: elections, terminations and owner pay",/2553|S election|revocation|terminat|reasonable compensation|2% shareholder|debt basis|built-in gain|passive investment income|LIFO recapture|QSub|7203/i,[
 {h:"Making and ending the election",b:["Form 2553 is due within 2 months and 15 days after the start of the year it should take effect, or any time in the year before. Every shareholder must consent.","An LLC that wants S status files Form 2553 only. It is treated as having elected corporate status too.","Late election relief: Rev. Proc. 2013-30, within 3 years and 75 days of the intended date, with reasonable cause.","Revocation: shareholders with more than 50% of the shares consent. Made by the 15th day of the 3rd month, it applies to that year; later, to the next year."]},
 {h:"When the election ends by itself",b:["A disqualifying event ends it on that date: an ineligible shareholder, or a second class of stock. The year splits into an S short year and a C short year.","Passive income: an S corporation that has C corporation earnings and profits and more than 25% passive investment income pays an entity-level tax. Three years in a row ends the election.","After a termination the corporation generally waits 5 tax years to elect again, unless the IRS consents. Inadvertent terminations can get relief."],
  ex:"Who cannot hold S stock: nonresident aliens, partnerships, corporations (except an S parent of a QSub) and most LLCs taxed as partnerships."},
 {h:"Paying a shareholder who works there",b:["A shareholder-employee must be paid reasonable wages, with payroll taxes, before taking distributions.","Health insurance for a more-than-2% shareholder goes in box 1 of the W-2 but is not subject to Social Security and Medicare tax. The shareholder may deduct it as self-employed health insurance.","Guaranteeing the corporation's bank loan does not create basis. Only money the shareholder lends directly does (debt basis)."]},
 {h:"Basis, losses and the built-in gains tax",v:{k:"flow",r:["Start with stock basis","Add income items","Subtract distributions","Subtract nondeductible expenses","Subtract losses and deductions"]},
  b:["Losses are limited to stock basis plus debt basis (Form 7203). Suspended losses carry forward while the person stays a shareholder.","Later income restores debt basis before stock basis. Repaying a loan whose basis was reduced triggers gain.","Built-in gains tax: 21% at the corporate level when a former C corporation sells assets that had appreciated before conversion, within 5 years."]}
]);
U(2,"C corporations: distributions and special taxes",/earnings and profits|E&P|constructive dividend|redemption|302|liquidation|331|336|accumulated earnings|personal holding|1244|1202|QSBS|163\(j\)|corporate estimated|charitable contribution limit/i,[
 {h:"What a distribution is",v:{k:"flow",r:["Dividend, to the extent of earnings and profits (current first, then accumulated)","Then a tax-free return of capital, down to zero stock basis","Then capital gain"]},
  b:["Earnings and profits measure the ability to pay dividends. They differ from taxable income: add tax-exempt income, subtract federal income tax, use slower depreciation.","Constructive dividends: personal expenses paid for a shareholder, excessive pay, bargain sales, below-market loans."]},
 {h:"Redemptions and liquidations",b:["A stock redemption is treated as a sale (capital gain or loss) if it is a complete termination, substantially disproportionate, or not essentially equivalent to a dividend. Otherwise it is a dividend.","Complete liquidation: the corporation recognizes gain or loss as if it sold its assets at fair market value, and the shareholders recognize gain or loss on what they receive minus stock basis. Two layers of tax.","A parent liquidating a subsidiary it owns 80% or more of recognizes nothing.","Section 1244: a loss on small business stock is ordinary up to $50,000 a year ($100,000 on a joint return)."]},
 {h:"Limits on a corporation's deductions",v:{k:"tiers",r:[["Capital losses","Only against capital gains. Back 3 years, forward 5",40],["Charitable gifts (2025)","10% of taxable income. Excess forward 5 years",55],["Net operating loss","Forward without limit, 80% of taxable income",70],["Business interest","Interest income + 30% of adjusted taxable income",85],["Dividends received","Deduct 50%, 65% or 100% by ownership",100]]},
  ex:"For 2025, adjusted taxable income is again figured before depreciation and amortization. Disallowed interest carries forward without limit (Form 8990)."},
 {h:"Penalty taxes and estimated tax",b:["Accumulated earnings tax: 20% on earnings kept beyond the reasonable needs of the business. The minimum credit is $250,000 ($150,000 for personal service corporations).","Personal holding company tax: 20% on undistributed personal holding company income.","Estimated tax is required when the expected tax is $500 or more, due the 15th day of the 4th, 6th, 9th and 12th months.","A large corporation (taxable income of $1 million or more in any of the prior 3 years) may use the prior-year safe harbor only for the first installment."]},
 {h:"Qualified small business stock (Section 1202)",b:["Gain on qualifying C corporation stock held more than 5 years can be excluded: 100% for stock acquired after September 27, 2010.","Stock issued after July 4, 2025: 50% after 3 years, 75% after 4 years, 100% after 5 years.","For that newer stock the cap per issuer is the greater of $15 million or 10 times basis, and the corporation's gross assets may not exceed $75 million when the stock is issued."]}
]);
U(2,"Selling and exchanging business property",/1231|1245|1250|recapture|291|installment sale|6252|like-kind|1031|involuntary conversion|1033|related party|267|1239|197|intangible|8594|4797/i,[
 {h:"What kind of gain is it?",v:{k:"flow",r:["Depreciable equipment (Section 1245): gain is ordinary up to the depreciation taken","Depreciable real estate (Section 1250): gain from straight-line depreciation is taxed at up to 25% for individuals","Whatever is left is Section 1231 gain","Net Section 1231 gain for the year: long-term capital gain","Net Section 1231 loss for the year: ordinary loss"]},
  ex:"Lookback: a net Section 1231 gain is ordinary to the extent of net Section 1231 losses in the prior 5 years. A C corporation also treats 20% of straight-line depreciation on real property (or the gain, if less) as ordinary (Section 291)."},
 {h:"Installment sales",b:["Gain is reported as payments come in: each payment times the gross profit percentage (Form 6252).","Depreciation recapture is all reported in the year of sale, even if no cash arrives that year.","Not allowed for inventory or dealer sales.","Basis in the installment note: the unpaid balance times (1 minus the gross profit percentage)."]},
 {h:"Postponing gain",v:{k:"cmp",a:["Like-kind exchange (Section 1031)",["Real property held for business or investment only","Identify the replacement within 45 days","Receive it within 180 days, or by the return due date","Cash or other property received is taxed up to the gain","Form 8824"]],b:["Involuntary conversion (Section 1033)",["Replace within 2 years after the end of the year gain is realized","3 years for condemned business or investment real estate","4 years for a main home in a federally declared disaster"]]},
  ex:"Like-kind exchange with a related party: if either side disposes of the property within 2 years, the postponed gain is recognized then."},
 {h:"Related parties and intangibles",b:["A loss on a sale to a related party is disallowed (Section 267). Related: spouse, brothers and sisters, ancestors, lineal descendants, and entities owned more than 50%. In-laws are not related.","The buyer may use the disallowed loss later to reduce gain on reselling the property.","Gain on selling depreciable property to a related party is ordinary income (Section 1239).","Goodwill, covenants not to compete, customer lists, licenses and franchises are amortized over 15 years (Section 197). Form 8594 allocates the price when a business is bought or sold."]}
]);
U(2,"Workers, fringe benefits and employer credits",/worker classification|SS-8|statutory employee|statutory nonemployee|accountable plan|fringe|achievement award|general business credit|3800|8941|45S|startup credit|backup withholding|trust fund recovery/i,[
 {h:"Employee or contractor",b:["The common-law test looks at three things: behavioral control, financial control and the relationship of the parties.","Either side can ask the IRS to decide with Form SS-8.","Statutory employees (certain drivers, full-time life insurance agents, home workers, traveling salespeople): a W-2 with box 13 checked, income and expenses on Schedule C, no self-employment tax.","Statutory nonemployees (direct sellers, licensed real estate agents, certain companion sitters): treated as self-employed."]},
 {h:"Reimbursements and tax-free benefits",b:["Accountable plan: a business purpose, substantiation, and return of any excess. Reimbursements under it are not wages.","Tax-free fringe benefits include no-additional-cost services, qualified employee discounts, working condition and de minimis benefits, qualified transportation ($325 a month in 2025), group-term life insurance up to $50,000 of coverage, educational assistance up to $5,250 and dependent care up to $5,000.","Length-of-service and safety awards of tangible property: up to $400 per employee ($1,600 under a qualified plan). Cash and gift cards are always wages.","Moving expense reimbursements are taxable wages, except for active-duty military."]},
 {h:"When payroll taxes are not paid",b:["Trust fund taxes are the income tax withheld from employees and the employees' share of Social Security and Medicare.","Trust fund recovery penalty: 100% of the unpaid trust fund taxes, charged personally to any responsible person who willfully failed to pay them.","Backup withholding rate: 24%.","An employer owing less than $2,500 for a quarter may pay with Form 941. Federal unemployment tax must be deposited once it passes $500."]},
 {h:"Credits for employers",b:["General business credit: Form 3800. Unused credit goes back 1 year and forward 20.","Small employer health insurance credit (Form 8941): fewer than 25 full-time equivalents, at least 50% of premiums paid through the SHOP marketplace, up to 50% of premiums, for 2 years in a row.","Retirement plan startup credit: employers with 100 or fewer employees, for the first 3 years of a new plan, plus a credit for employer contributions.","Paid family and medical leave credit: 12.5% of the wages paid during leave that pays at least half of normal wages, rising to 25% at full pay, for up to 12 weeks per employee."]}
]);
U(2,"Retirement plans for a small business",/SEP|SIMPLE|401\(k\)|defined benefit|vesting|top-heavy|highly compensated|5500|prohibited transaction|annual additions|profit-sharing/i,[
 {h:"Three plans, 2025 limits",v:{k:"cmp",a:["SEP-IRA",["Employer money only","Up to 25% of pay (about 20% of net self-employment earnings for an owner), capped at $70,000","Pay counted up to $350,000","Can be set up and funded by the return due date, with extensions"]],b:["SIMPLE IRA and 401(k)",["SIMPLE: $16,500 deferral, $3,500 catch-up at 50; employers with 100 or fewer employees; match up to 3% or give 2%; set up by October 1","401(k): $23,500 deferral, $7,500 catch-up at 50, $11,250 at ages 60 to 63; total additions $70,000"]]},
  ex:"A defined benefit plan can fund a yearly benefit of up to $280,000 for 2025."},
 {h:"Rules that protect the rank and file",b:["Vesting of employer contributions: a 3-year cliff, or graded over 2 to 6 years (20% a year). An employee's own deferrals are always 100% vested.","Top-heavy plan: more than 60% of the balances belong to key employees. It must give minimum contributions to the others.","Highly compensated employee for 2025 testing: pay above $160,000 in the lookback year.","Employer deduction limit for a profit-sharing plan or SEP: 25% of the participants' eligible pay."]},
 {h:"Filing and where the deduction goes",b:["Form 5500 is due the last day of the 7th month after the plan year ends: July 31 for a calendar-year plan. Form 5558 adds 2½ months.","Form 5500-EZ, for a one-participant plan, is required once plan assets pass $250,000 at year end.","A self-employed person deducts their own contribution on Schedule 1, not on Schedule C. Contributions for employees go on Schedule C."]},
 {h:"Prohibited transactions",b:["Self-dealing with a plan or IRA: borrowing from it, selling property to it, or using it as security for a loan.","IRA: the whole account is treated as distributed on January 1 of that year.","Employer plan: excise taxes on the disqualified person."]}
]);
U(2,"Trusts and estates in depth",/simple trust|complex trust|grantor|DNI|65-day|income in respect|IRD|645|estate tax year|1041|gift tax|portability|DSUE|annual exclusion/i,[
 {h:"Three kinds of trust",v:{k:"tiers",r:[["Simple trust","Must pay out all income each year. No gifts to charity, no principal paid out. Exemption $300",40],["Complex trust","Anything else: may keep income, pay out principal, or give to charity. Exemption $100",70],["Grantor trust","The creator kept control, so the income is taxed on the creator's own return",100]]},
  ex:"An estate's exemption is $600. Brackets are compressed: for 2025 the 37% rate starts at $15,650 of taxable income."},
 {h:"Who pays the tax: distributable net income",b:["Distributable net income (DNI) is the ceiling on the deduction the trust or estate takes for distributions, and on what the beneficiaries are taxed on.","Income keeps its character in the beneficiary's hands.","65-day rule: the trustee or executor may elect to treat distributions made in the first 65 days of the next year as made in the year just ended."]},
 {h:"Filing Form 1041",b:["An estate files if gross income is $600 or more. A trust files if it has any taxable income, gross income of $600 or more, or a nonresident alien beneficiary.","Due the 15th day of the 4th month after year end; Form 7004 adds 5½ months.","An estate may choose a fiscal year. A trust generally must use the calendar year.","Section 645 election: a qualified revocable trust can be treated as part of the estate: one Form 1041, a fiscal year and the $600 exemption, for up to 2 years after death.","Final year: unused capital loss and net operating loss carryovers and excess deductions pass to the beneficiaries."]},
 {h:"Income in respect of a decedent, gifts and portability",b:["Income in respect of a decedent is income the person had earned but not received before death, such as a last paycheck or an IRA. Whoever receives it reports it, with the same character.","The recipient may deduct the estate tax that was caused by that income.","2025 gifts: annual exclusion $19,000 per recipient; $190,000 to a spouse who is not a U.S. citizen; basic exclusion amount $13,990,000. Form 709 is due April 15.","Portability: an estate not otherwise required to file can still elect to pass the unused exclusion to the surviving spouse on a Form 706 filed within 5 years of death."]}
]);
U(2,"Exempt organizations and farmers",/501\(c\)\(3\)|exempt organization|1023|990|unrelated business|UBI|private foundation|lobbying|farm|Schedule F|crop insurance|livestock|income averaging/i,[
 {h:"Becoming and staying exempt",b:["Section 501(c)(3) purposes: religious, charitable, scientific, testing for public safety, literary, educational, fostering amateur sports, and preventing cruelty to children or animals.","Form 1023, or Form 1023-EZ when projected yearly gross receipts are $50,000 or less and assets are $250,000 or less. Filed within 27 months of formation, exemption dates back to the start. Churches need not apply.","Campaigning for or against a candidate is absolutely forbidden. Lobbying may not be a substantial part of the activities.","Not filing a required return or notice for 3 years in a row revokes the exemption automatically."]},
 {h:"Which Form 990",v:{k:"tiers",r:[["990-N (e-Postcard)","Gross receipts normally $50,000 or less",25],["990-EZ","Gross receipts under $200,000 and assets under $500,000",50],["990","Everyone else",75],["990-PF","Private foundations, whatever their size",100]]},
  ex:"Due the 15th day of the 5th month after year end: May 15 for a calendar year. Form 8868 extends the time to file."},
 {h:"Unrelated business income",b:["Income from a trade or business that is regularly carried on and not substantially related to the exempt purpose.","Form 990-T is required when gross unrelated business income is $1,000 or more. There is a $1,000 specific deduction.","Not unrelated business income: work done by volunteers, selling donated goods, activities for the convenience of members or employees, and passive income such as dividends, interest, royalties and rents from real property (unless debt-financed)."]},
 {h:"Farmers",b:["Farm income and expenses go on Schedule F. Farmers may average income over prior years on Schedule J.","A farm net operating loss may be carried back 2 years.","Crop insurance proceeds can be deferred to the next year if the crop would normally have been sold then.","Livestock sold because of drought or weather: the gain can be postponed if replaced within 2 to 4 years, or the income deferred one year."]}
]);
/* ---------------- Part 3: Representation, practices and procedures ---------------- */
U(3,"Practice rights in detail",/who may practice|limited practice|unenrolled|AFSP|record of completion|Tax Court|former IRS|former government|10\.25|10\.7|practice of law/i,[
 {h:"Three levels of practice",v:{k:"tiers",r:[["Unlimited","Attorneys, CPAs and enrolled agents: any taxpayer, any matter, any IRS office",100],["Limited by subject","Enrolled actuaries and enrolled retirement plan agents: plan matters only",60],["Limited by return","Annual Filing Season Program holders: only returns they prepared and signed",30]]},
  ex:"An unenrolled preparer with an AFSP record may appear before revenue agents, customer service and the Taxpayer Advocate Service. Not before Appeals, collection or revenue officers."},
 {h:"Who may act without being a practitioner",b:["An individual for themselves, or for a family member.","An officer or full-time employee for the employer.","A general partner for the partnership.","A trustee, executor or administrator for the trust or estate."]},
 {h:"What an enrolled agent cannot do",b:["Practice in Tax Court, unless admitted by passing the Tax Court's exam for non-attorneys.","Represent anyone in District Court or the Court of Federal Claims.","Practice law. Nothing in Circular 230 authorizes that.","Notarize a document in a matter where they are employed or have an interest."]},
 {h:"Former IRS employees",b:["Never: represent anyone in a particular matter they personally and substantially worked on.","For 2 years: matters that were under their official responsibility in their last year of service.","Their firm may take such a matter only if the former employee is screened from it.","A former employee with at least 5 years of continuous technical IRS work may apply for enrollment without the exam, within 3 years of leaving."]}
]);
U(3,"Standards for returns and advice",/10\.34|10\.37|reasonable basis|substantial authority|more likely than not|8275|10\.21|10\.22|omission|written advice|rely|competence|10\.35/i,[
 {h:"How strong must a position be?",v:{k:"tiers",r:[["Reasonable basis","About a 20% chance. Allowed only with disclosure (Form 8275; 8275-R if against a regulation)",20],["Substantial authority","About 40% or better. No disclosure needed",40],["More likely than not","Over 50%. Required for tax shelters and reportable transactions",55]]},
  ex:"Below reasonable basis a position is frivolous. A practitioner may not sign or advise on it."},
 {h:"What counts as authority",v:{k:"cmp",a:["Counts",["The Code and regulations","Court cases","Revenue rulings and procedures, treaties","Committee reports, the Blue Book","Private letter rulings, notices and announcements"]],b:["Does not count",["IRS publications","IRS forms and instructions","IRS.gov pages","Treatises and articles"]]}},
 {h:"When you find a mistake",b:["A practitioner who learns of a client's error or omission must promptly tell the client, and explain the consequences.","There is no duty to fix it, to amend the return, or to tell the IRS.","You may rely on what a client tells you in good faith without checking it. You may not ignore what it implies: if it looks wrong, inconsistent or incomplete, ask.","You may rely on another person's work if you used reasonable care in engaging and supervising them."]},
 {h:"Written advice and competence",b:["Written advice must rest on reasonable factual and legal assumptions and consider all relevant facts.","It may not rely on unreasonable statements by the client, and may not take into account the chance of being audited.","Competence can be acquired by study or by consulting someone who has it.","Whoever has principal authority over a firm's tax practice must take reasonable steps to make sure everyone follows Circular 230."]}
]);
U(3,"Client records, confidentiality and privilege",/10\.28|client records|7216|6713|consent|7525|privilege|10\.20|retention|36 months|advertising|conflict|10\.29|10\.30|fee/i,[
 {h:"The client's records",b:["On request, promptly return every record the client needs to meet federal tax obligations.","A fee dispute does not change this. You may keep copies.","Records the IRS asks you for must be handed over promptly, unless you believe in good faith they are privileged. If you do not have them, say who does."]},
 {h:"Tax return information is confidential",b:["Disclosing or using return information without consent is a crime (Section 7216): up to $1,000 and a year in prison.","Civil penalty (Section 6713): $250 for each disclosure, up to $10,000 a year.","A consent must be separate, written, signed and dated before the use or disclosure, and specific. It lasts 1 year unless it says otherwise.","Sending Social Security numbers to a preparer outside the United States needs its own specific consent."]},
 {h:"The practitioner privilege",b:["Confidential tax advice from a practitioner is protected like attorney-client advice (Section 7525).","Only in noncriminal tax matters before the IRS or a federal court.","Not for return preparation.","Not for written communications that promote a tax shelter."]},
 {h:"Conflicts, fees and advertising",b:["A conflict may be accepted only if you reasonably believe you can serve each client competently, the law allows it, and each client gives informed consent confirmed in writing within 30 days. Keep the consents 36 months.","Contingent fees are allowed only for an IRS exam of an original return, an amended return or refund claim filed within 120 days of an exam notice, a claim only for interest and penalties, or a court case.","Published fees must be honored for at least 30 days.","Advertising: never false or misleading, never 'certified', never the IRS logo. An enrolled agent may say 'enrolled to practice before the Internal Revenue Service'."]},
 {h:"How long to keep things",v:{k:"calc",r:[["Returns, or a list of them","3 years"],["Form 8867 records","3 years"],["Advertising copies","36 months"],["Conflict consents","36 months"],["CE records","4 years"]]},
  ex:"The 3 years for return copies run from the close of the return period, which is the 12 months beginning July 1."}
]);
U(3,"Penalties on taxpayers and how to remove them",/accuracy-related|6662|civil fraud|6663|failure to file|failure-to-file|failure to pay|6651|frivolous|6702|7201|7203|7206|reasonable cause|first-time abate|abatement|interest abatement|substantial understatement/i,[
 {h:"The civil penalties",v:{k:"tiers",r:[["Late filing","5% of the unpaid tax per month, up to 25%",50],["Late payment","0.5% per month",15],["Accuracy-related","20% of the underpayment (40% for gross valuation misstatements)",40],["Civil fraud","75% of the part due to fraud",100]]},
  ex:"Return due in 2026 and more than 60 days late: the minimum late-filing penalty is the smaller of $525 or 100% of the tax due."},
 {h:"Details the exam asks about",b:["Late payment drops to 0.25% a month during an installment agreement on a timely filed return, and rises to 1% a month 10 days after a notice of intent to levy.","Substantial understatement for an individual: more than the greater of 10% of the correct tax or $5,000.","Frivolous return: $5,000. The same for frivolous hearing requests, offers and installment requests.","Erroneous refund claim: 20% of the excessive amount, unless there was reasonable cause.","The IRS must prove fraud by clear and convincing evidence."]},
 {h:"The criminal side",v:{k:"calc",r:[["Evasion (7201), felony","5 years"],["False statements (7206), felony","3 years"],["Failure to file (7203), misdemeanor","1 year"]]},
  b:["Fines: up to $100,000 for the two felonies ($500,000 for corporations) and $25,000 for willful failure to file ($100,000 for corporations)."]},
 {h:"Getting a penalty removed",b:["Reasonable cause: ordinary business care and prudence, defeated by events such as death, serious illness, disaster or records that could not be obtained.","First-time abatement: for late filing, late payment and late deposit penalties when the prior 3 years are clean, all returns are filed and the tax is paid or arranged.","From returns due January 1, 2027 the IRS replaces first-time abatement with automatic relief. The current exam window still tests first-time abatement.","Interest is abated only for unreasonable IRS errors or delays in ministerial or managerial acts. Never for reasonable cause.","Before assessment: answer the notice or go to Appeals. After assessment: ask for abatement (Form 843 or a letter). After paying: file a refund claim."]}
]);
U(3,"Preparer penalties, due diligence and discipline",/6694|6695|due diligence|8867|6700|6701|7407|OPR|complaint|administrative law judge|censure|suspension|disbar|10\.50|10\.51|10\.76|expedited/i,[
 {h:"Penalties on the preparer",v:{k:"cmp",a:["Understating the client's tax (6694)",["Unreasonable position: the greater of $1,000 or 50% of the fee","Willful or reckless conduct: the greater of $5,000 or 75% of the fee","Avoided by substantial authority, or reasonable basis with disclosure, or reasonable cause and good faith"]],b:["Procedural failures (6695)",["No copy to the client","Not signing, or no PTIN","No copy or list kept","Cashing a client's refund check","Failing due diligence"]]}},
 {h:"Due diligence, four duties",v:{k:"flow",r:["Knowledge: make reasonable inquiries and record the answers","Complete Form 8867","Compute the credits on the worksheets","Keep the records for 3 years"]},
  ex:"It covers the earned income credit, the child tax credit and its relatives, the American opportunity credit and head of household status."},
 {h:"Sanctions under Circular 230",b:["Censure: a public reprimand. The practitioner keeps practicing.","Suspension: up to 59 months.","Disbarment: at least 5 years before asking to come back.","Monetary penalty: up to the gross income from the conduct, on the practitioner and, if it knew or should have known, the firm.","Only willful, reckless or grossly incompetent conduct is sanctioned. Simple negligence alone is not, though it can still bring a preparer penalty."]},
 {h:"How a discipline case runs",v:{k:"flow",r:["The Office of Professional Responsibility files a complaint","The practitioner answers within 30 days. No answer admits the charges","Hearing before an Administrative Law Judge","Appeal to the Treasury Appellate Authority within 30 days"]},
  ex:"Proof needed: clear and convincing evidence for disbarment, a suspension of 6 months or more, or a monetary penalty. A preponderance for censure or a shorter suspension."}
]);
U(3,"Appeals, Tax Court and refund suits",/protest|Appeals|ex parte|hazards|notice of deficiency|90-day|Tax Court|small case|refund suit|District Court|Federal Claims|Flora|Fast Track|burden of proof|7491|audit reconsideration|docketed/i,[
 {h:"From the exam to Appeals",v:{k:"flow",r:["30-day letter: the examiner's proposed changes","Protest to Appeals within 30 days","Formal written protest if more than $25,000 is in dispute for any period; a small case request if less","Appeals weighs the hazards of litigation and settles, or issues a notice of deficiency"]},
  ex:"Appeals does not raise new issues and may not discuss the merits with the examiner unless the taxpayer's side can take part."},
 {h:"The notice of deficiency",b:["Also called the 90-day letter. The taxpayer has 90 days to petition the Tax Court, or 150 if the notice is addressed outside the United States.","The IRS cannot assess the tax during that period.","Tax Court is the only court where the tax does not have to be paid first.","Small case: $50,000 or less per year including penalties. Informal, and the decision cannot be appealed."]},
 {h:"Suing for a refund",b:["Pay the full tax first.","File a refund claim.","Sue after 6 months, or after the claim is denied, and within 2 years of the notice of disallowance.","The suit goes to District Court (a jury is available) or the Court of Federal Claims."]},
 {h:"Other tools",b:["Fast Track Settlement: an Appeals officer mediates while the case stays with the examiner.","Audit reconsideration: asks the IRS to look again at an audit assessment, for example when the taxpayer never appeared or has new documents. Not available if the taxpayer agreed and paid.","The burden of proof moves to the IRS when the taxpayer brings credible evidence, kept records, substantiated the items and cooperated.","A taxpayer may petition to quash a third-party summons within 20 days of the notice."]}
]);
U(3,"Time limits: assessment, refunds and extensions",/statute of limitations|assessment statute|6501|refund statute|6511|lookback|872|financially disabled|early-filed|substitute for return|6020|overpayment interest|1040-X|Form 843/i,[
 {h:"How long the IRS has to assess",v:{k:"calc",r:[["Normal","3 years"],["More than 25% of gross income left out","6 years"],["Fraud, or no return filed","No limit"]]},
  b:["The 3 years run from the later of the due date or the date filed. A return filed early counts as filed on the due date.","If a required foreign information return is missing, the period for the whole return stays open until 3 years after the IRS receives it."]},
 {h:"Agreeing to more time",b:["Form 872 extends the period to a fixed date.","Form 872-A is open-ended. It is ended by Form 872-T, 90 days after that form.","The IRS must tell the taxpayer they may refuse, or limit the extension to particular issues."]},
 {h:"How long the taxpayer has to claim a refund",b:["The later of 3 years from filing the return or 2 years from paying the tax.","Filed within the 3 years: the refund can reach tax paid in the 3 years (plus any extension) before the claim.","Otherwise: only tax paid in the 2 years before the claim.","Withholding and estimated tax count as paid on the original due date.","Longer: 7 years for a bad debt or worthless security, and the clock stops while a taxpayer is financially disabled."],
  ex:"Forms: 1040-X for individuals, 1120-X for corporations, and Form 843 for penalties and interest."},
 {h:"When the taxpayer never filed",b:["The IRS may prepare a substitute for return from information returns, usually with single or married-filing-separately status and only the standard deduction.","The taxpayer can still file a real return to replace it, which usually lowers the tax.","No interest is paid on a refund issued within 45 days of the due date or the filing date."]}
]);
U(3,"Liens, levies and collection hearings",/lien|NFTL|12277|14135|14134|levy|668|wage levy|bank levy|jeopardy|Federal Payment Levy|CDP|equivalent hearing|12153|Collection Appeals|9423|seizure|passport/i,[
 {h:"Lien and levy are different things",v:{k:"cmp",a:["Lien",["A legal claim on property as security for the debt","Arises automatically after assessment, notice and demand, and nonpayment","The Notice of Federal Tax Lien makes it public"]],b:["Levy",["Actually takes property: wages, bank accounts, receivables","Needs notice and demand, then a final notice at least 30 days before","A wage levy continues until released"]]}},
 {h:"Dealing with a lien",v:{k:"tiers",r:[["Withdrawal (Form 12277)","Removes the public notice",35],["Discharge (Form 14135)","Frees one specific property",65],["Subordination (Form 14134)","Lets another creditor go ahead of the IRS",100]]},
  b:["After filing the notice the IRS must tell the taxpayer within 5 business days. The taxpayer then has 30 days to ask for a hearing.","The lien is released within 30 days after the debt is paid, becomes unenforceable, or a bond is accepted."]},
 {h:"Levy details",b:["A bank holds levied funds for 21 days before sending them, which gives time to fix mistakes.","Federal Payment Levy Program: a continuous levy of up to 15% of Social Security benefits and other federal payments.","The IRS must release a levy when the tax is paid, the collection period has ended, it causes economic hardship, or an installment agreement is made.","Seizing a main home needs approval from a federal judge or magistrate, and is not allowed for a debt of $5,000 or less.","A levy on an IRA is taxable income but is not hit by the 10% early distribution tax. A voluntary withdrawal to pay the IRS is."]},
 {h:"Three kinds of hearing",v:{k:"tiers",r:[["Collection Due Process","Asked for within 30 days on Form 12153. Stops the levy and the collection clock. Tax Court review within 30 days",100],["Equivalent hearing","Asked for within 1 year when the 30 days were missed. No court review, levy not stopped",60],["Collection Appeals Program","Form 9423. Fast, covers liens, levies and installment agreement denials. Final, no court",30]]},
  ex:"State refund levies, jeopardy levies, federal contractor levies and certain employment tax levies get their hearing after the levy, not before."},
 {h:"Passports",b:["The IRS certifies seriously delinquent tax debt to the State Department, which can deny or revoke a passport.","2025 threshold: more than $64,000 of assessed tax, penalties and interest ($66,000 for 2026), with a lien filed and hearing rights used up, or a levy.","Not certified while the taxpayer has an installment agreement, a pending or accepted offer, a timely hearing request, or a pending innocent spouse claim."]}
]);
U(3,"Ways to pay less or pay later",/installment agreement|9465|433|guaranteed|streamlined|partial payment|offer in compromise|OIC|656|reasonable collection potential|RCP|currently not collectible|CNC|CSED|collection statute|financial standards/i,[
 {h:"Installment agreements",v:{k:"tiers",r:[["Guaranteed","Tax of $10,000 or less, paid within 3 years, clean 5-year record. The IRS must grant it",30],["Streamlined","Assessed balance up to $50,000, paid within 72 months. No financial statement",60],["Partial payment","Pays less than the full debt before the collection period ends. Full financial disclosure, reviewed every 2 years",85],["In-business trust fund express","A business owing $25,000 or less of payroll tax, paid within 24 months",100]]},
  ex:"All returns must be filed, and future taxes filed and paid on time. Interest and penalties keep running. Request on Form 9465."},
 {h:"Offer in compromise",b:["Three grounds: doubt as to liability, doubt as to collectibility, and effective tax administration.","Form 656 with a financial statement, and a $205 fee (waived for low-income taxpayers). Doubt as to liability uses Form 656-L, with no fee.","Lump sum offer (5 or fewer payments): 20% with the offer, not refundable. Periodic offer: the first payment with the offer, then keep paying while it is considered.","The taxpayer must have filed all returns, be current on estimated tax and deposits, and not be in an open bankruptcy."]},
 {h:"How the IRS values an offer",v:{k:"flow",r:["Net realizable equity in assets","Plus future disposable income: 12 months for a lump sum offer, 24 months for a periodic offer","Equals the reasonable collection potential: the basis for the offer amount"]},
  b:["An offer not decided within 24 months is treated as accepted.","After acceptance the taxpayer must file and pay on time for 5 years, and the IRS keeps refunds through the year of acceptance."]},
 {h:"Not collectible, and the 10-year clock",b:["Currently not collectible: collection is paused because paying would cause hardship. Interest and penalties continue, and refunds can still be taken.","The IRS has 10 years from assessment to collect.","That clock stops while an offer or installment request is pending, during a Collection Due Process hearing, in bankruptcy, and while the taxpayer is outside the country 6 months or more.","A levy is generally not allowed while an offer or installment request is pending, for 30 days after a rejection, and during an appeal of it."]},
 {h:"What the IRS allows for living expenses",b:["National Standards (food, clothing, housekeeping, personal care, miscellaneous) and out-of-pocket health care are allowed without proof.","Local Standards cover housing and utilities, and transportation: the lower of the actual cost or the standard."]}
]);
U(3,"Innocent spouse, bankruptcy and the trust fund penalty",/innocent spouse|6015|8857|bankruptcy|automatic stay|discharg|trust fund recovery|6672|4180|Letter 1153|responsible person/i,[
 {h:"Relief from a joint return",v:{k:"tiers",r:[["Traditional relief","An understatement the requesting spouse did not know about",35],["Separation of liability","Divorced, widowed, legally separated, or living apart for 12 months",65],["Equitable relief","When the other two do not fit. Also covers tax shown on the return but not paid",100]]},
  ex:"The first two must be requested within 2 years of the first collection action against the requesting spouse. Equitable relief can be requested while the tax can still be collected."},
 {h:"Bankruptcy",b:["Income tax can be discharged only if the return was due more than 3 years before the bankruptcy, was filed more than 2 years before, the tax was assessed more than 240 days before, and there was no fraud or evasion.","The automatic stay stops IRS collection while the case is open.","The 10-year collection period is suspended for the stay plus 6 months."]},
 {h:"The trust fund recovery penalty",b:["Trust fund taxes: income tax withheld from employees and their share of Social Security and Medicare. Not the employer's share, and not unemployment tax.","A responsible person had the duty and authority to collect and pay them: officers, owners, check signers, sometimes a bookkeeper.","Willful means they knew and paid other creditors instead.","The penalty equals 100% of the unpaid trust fund tax and is personal."]},
 {h:"How the penalty is proposed",v:{k:"flow",r:["Interview on Form 4180","Letter 1153 proposes the penalty","60 days to appeal (75 if outside the United States)"]}}
]);
U(3,"Representing a client: authorizations and taxpayer rights",/2848|8821|CAF|Tax Pro Account|third-party designee|third-party contact|bypass|interview|Taxpayer Bill of Rights|Taxpayer Advocate|Form 911|Low Income Taxpayer|summons|IDR|4564/i,[
 {h:"Two forms, two powers",v:{k:"cmp",a:["Form 2848, power of attorney",["Lets an eligible practitioner represent and act for the taxpayer","Each spouse on a joint return signs a separate form","Can cover any past period and up to 3 years ahead"]],b:["Form 8821, information authorization",["Lets anyone receive and inspect information","No representation","Same rule for future periods"]]},
  ex:"The checkbox designee on a return can only discuss the processing of that return, and only for 1 year from its due date."},
 {h:"Managing an authorization",b:["A new Form 2848 for the same matter revokes the old one, unless the box to keep it is checked.","To revoke: write REVOKE across the top of a copy, sign, date and send it.","Tax Pro Account lets a practitioner with a CAF number send the request to the client's IRS online account, where the client signs it.","A representative may sign a client's return only for disease or injury, continuous absence from the country for 60 days before the due date, or other good cause with IRS permission."]},
 {h:"The taxpayer's rights in an exam",b:["A representative with a Form 2848 may attend in the taxpayer's place, unless the taxpayer is summoned.","The taxpayer may stop an interview to consult a representative, and may audio-record with 10 days' notice.","The IRS must give at least 45 days' notice before contacting third parties.","The IRS may go around a representative who unreasonably delays the case, with a supervisor's approval.","An unanswered Information Document Request leads to a delinquency notice, then a pre-summons letter, then a summons."]},
 {h:"Where a taxpayer can get help",b:["Taxpayer Bill of Rights: ten rights, including to be informed, to pay no more than the correct tax, to appeal in an independent forum, to privacy and to keep a representative.","Taxpayer Advocate Service: independent, inside the IRS, for hardship and problems the normal channels did not fix. Form 911.","Low Income Taxpayer Clinics: independent of the IRS. They represent taxpayers with income generally at or below 250% of the poverty guidelines, usually in disputes under $50,000."]}
]);
U(3,"Filing mechanics every preparer must know",/due date|4868|7502|timely mail|abroad|information return|e-file mandate|8948|reject|8879|amended|8888|direct deposit|PATH Act|IP PIN|8822|CP53E|6721/i,[
 {h:"Deadlines",v:{k:"time",r:[["January 31","Forms W-2 and 1099-NEC, to recipients and to the government"],["March 15","Forms 1065 and 1120-S"],["April 15","Forms 1040, 1120 and 1041. Form 4868 extends filing to October 15, not payment"],["May 15","Form 990"],["June 15","Citizens living abroad: automatic 2 extra months"]]},
  ex:"Timely mailed is timely filed: a postmark, or handing it to a designated private delivery service, by the due date. A due date on a weekend or holiday moves to the next business day."},
 {h:"E-file rules",b:["A preparer who expects to file 11 or more individual or trust returns must e-file them. A client who insists on paper signs a statement, and Form 8948 explains the exception.","10 or more information returns in a year must be filed electronically.","Rejected return: tell the client within 24 hours. To stay timely, resend within 5 calendar days, or mail a paper return by the later of the due date or 10 calendar days after the notice, with an explanation.","Form 1040-X can be e-filed for the current year and the 2 prior years."]},
 {h:"Refunds",b:["Direct deposit into up to 3 accounts (Form 8888), and no more than 3 refunds into one account per year.","A preparer may not deposit a client's refund into the preparer's own account, or set the fee by the size of the refund.","A return claiming the earned income credit or the additional child tax credit: no refund before February 15, and the whole refund waits.","Paper refund checks are being phased out. A 2025 return with no bank details is still processed; the IRS sends Notice CP53E asking for them."]},
 {h:"Identity and information return penalties",b:["Identity Protection PIN: 6 digits, required on the return of anyone who has one. Anyone may opt in.","Change of address: Form 8822 for a home, Form 8822-B for a business or its responsible party, within 60 days.","Late information returns due in 2026: $60 each if corrected within 30 days, $130 by August 1, $340 after that. Intentional disregard: at least $680 each."]}
]);
